#pragma once

// The fraction of a spell's (or a troop's direct hit's) damage it deals to a Crown Tower. Generated by bot-77's
// scripts/sim_spell_tower.py from RoyaleAPI cr-api-data (crown_tower_damage_percent, 2023-12).
// -1 for spells without a published value (they keep 100%).
inline float crownTowerFractionForCard(int cardId) {
    switch (cardId) {
        case 3: return 0.30f;  // Arrows (-70%)
        case 7: return 0.30f;  // Fireball (-70%)
        case 29: return 0.30f;  // Zap (-70%)
        case 30: return 0.25f;  // Rocket (-75%)
        case 31: return 0.30f;  // Lightning (-70%)
        case 33: return 0.20f;  // The Log (-80%)
        case 100: return 0.30f;  // Giant Snowball (-70%)
        case 107: return 0.30f;  // Freeze (-70%)
        case 124: return 0.30f;  // Zap (-70%)
        case 158: return 0.30f;  // Giant Snowball (-70%)
        case 52: return 0.25f;  // Miner (-75%)
        default: return -1.0f;
    }
}
